// Build the requisition form schema the React app consumes.
//
// The app knows field *keys*, never ClickUp UUIDs, so the mapping lives here.
// A key this workspace cannot supply is reported in `missingKeys` rather than
// omitted quietly — the form refuses to open on a missing key, which is the
// only safe behaviour when the alternative is dropping a manager's answers.

const NAME_TO_KEY = {
  'company': 'company',
  'department': 'department',
  'cost centre': 'costCentre',
  'cost center': 'costCentre',
  'section': 'section',
  'work location': 'location',
  'location': 'location',
  'job grade': 'jobGrade',
  'job code no': 'jobCodeNo',
  'job code': 'jobCodeNo',
  'position type': 'positionType',
  'position new replacement': 'newOrReplacement',
  'total sub positions': 'totalSubPositions',
  'recruitment type': 'recruitmentType',
  'requesting manager': 'requestingManager',
  'reporting to': 'reportingTo',
  'others reporting indirectly': 'othersReportingIndirectly',
  'job overview': 'jobOverview',
  'key responsibilities outcomes': 'keyResponsibilitiesOutcomes',
  'key responsibilities and outcomes': 'keyResponsibilitiesOutcomes',
  'educational qualification': 'educationalQualification',
  'relevant skills experience attributes': 'relevantSkillsExperienceAttributes',
  'relevant skills experience and attributes': 'relevantSkillsExperienceAttributes',
  'previous failures successes': 'previousFailuresSuccesses',
  'competitive advantage': 'competitiveAdvantage',
  '6 months objectives': 'sixMonthsObjectives',
  'potential career path': 'potentialCareerPath',
  'position requirements': 'positionRequirements',
  'assessment stages required': 'assessmentStagesRequired',
  'interview panel': 'interviewPanel',
  'requisition raised': 'requisitionRaised',
};

// Every key the form writes to. Kept in step with REQUIRED_FIELD_KEYS in
// src/requisition/schema.ts.
const REQUIRED = [
  'company', 'department', 'costCentre', 'location',
  'positionType', 'newOrReplacement', 'totalSubPositions',
  'recruitmentType', 'requestingManager', 'reportingTo',
  'othersReportingIndirectly', 'jobOverview', 'keyResponsibilitiesOutcomes',
  'educationalQualification', 'relevantSkillsExperienceAttributes',
  'previousFailuresSuccesses', 'competitiveAdvantage', 'sixMonthsObjectives',
  'potentialCareerPath', 'positionRequirements', 'assessmentStagesRequired',
  'interviewPanel', 'requisitionRaised',
];

// The owning department, shown as quiet secondary text beside each item.
// Managers tick more honestly when they can see who they create work for.
// TODO(kenafric): two owners are unconfirmed, and the list has no motorcycle
// or scooter option that a rider or field-sales role would need.
const PROVISIONING_OWNER = {
  'Email Address': 'ICT',
  'Laptop/Computer/Connectivity': 'ICT',
  'SAP Credentials': 'ICT',
  'Office Space & Accessories': 'HR',
  'Pick-up': 'Garage',
  'Saloon Vehicle': 'Garage',
  'Business Cards - Role Based': 'owner TBC',
  'Fuel Allowance': 'owner TBC',
};

// The client confirmed the work-location list: two sites, no inferred entries.
const PROVISIONAL_LOCATIONS = new Set([]);

const norm = (s) => (s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();

const TYPE_MAP = {
  drop_down: 'drop_down',
  labels: 'labels',
  users: 'people',
  number: 'number',
  date: 'date',
  text: 'text',
  textarea: 'textarea',
  short_text: 'text',
};

const sourceFields = $('ClickUp - List Fields').first().json.fields || [];

const fields = {};
for (const field of sourceFields) {
  const key = NAME_TO_KEY[norm(field.name)];
  if (!key) continue;

  const options = (field.type_config?.options || [])
    .slice()
    .sort((a, b) => (a.orderindex ?? 0) - (b.orderindex ?? 0))
    .map((option) => {
      const label = option.name ?? option.label ?? '';
      const mapped = { label };
      if (key === 'positionRequirements' && PROVISIONING_OWNER[label]) {
        mapped.note = PROVISIONING_OWNER[label];
      }
      if (key === 'location' && PROVISIONAL_LOCATIONS.has(label)) {
        mapped.provisional = true;
      }
      return mapped;
    });

  // Option UUIDs are deliberately not forwarded: the app submits labels, and
  // the submit workflow resolves them again on the way back in.
  fields[key] = {
    key,
    clickupName: field.name,
    type: TYPE_MAP[field.type] || 'text',
    ...(options.length ? { options } : {}),
  };
}

const teams = $('ClickUp - Workspace Members').first().json.teams || [];
const team = teams.find((t) => String(t.id) === '9012912728') || teams[0] || {};
const members = (team.members || [])
  .map((entry) => entry.user || entry)
  .filter((user) => user && user.id && !user.deleted)
  .map((user) => ({
    clickupUserId: user.id,
    name: user.username || user.email || String(user.id),
    email: user.email,
    initials: user.initials,
  }))
  .sort((a, b) => a.name.localeCompare(b.name));

const missingKeys = REQUIRED.filter((key) => !fields[key]);

// TODO(kenafric): the active-employee register is not exposed yet, so "who is
// being replaced" falls back to free text in the app.
return [{ json: { fields, members, employees: [], missingKeys } }];
